  1053  /******************/
  1054
  1055  void *
  1056  UA_Array_new(size_t size, const UA_DataType *type) {
  1057      if(size > UA_INT32_MAX)
  1058          return NULL;
  1059      if(size == 0)
  1060          return UA_EMPTY_ARRAY_SENTINEL;
  1061      return UA_calloc(size, type->memSize);
  1062  }
  1063
  1064  UA_StatusCode
  1065  UA_Array_copy(const void *src, size_t size,
  1066                void **dst, const UA_DataType *type) {
  1067      if(size == 0) {
  1068          if(src == NULL)
  1069              *dst = NULL;
  1070          else
  1071              *dst= UA_EMPTY_ARRAY_SENTINEL;
  1072          return UA_STATUSCODE_GOOD;
  1073      }
  1074
  1075      if(!type)
  1076          return UA_STATUSCODE_BADINTERNALERROR;
  1077
  1078      /* calloc, so we don't have to check retval in every iteration of copying */
  1079      *dst = UA_calloc(size, type->memSize);
  1080      if(!*dst)
  1081          return UA_STATUSCODE_BADOUTOFMEMORY;
  1082
  1083      if(type->pointerFree) {
  1084          memcpy(*dst, src, type->memSize * size);
  1085          return UA_STATUSCODE_GOOD;
  1086      }
  1087
  1088      uintptr_t ptrs = (uintptr_t)src;
  1089      uintptr_t ptrd = (uintptr_t)*dst;
  1090      UA_StatusCode retval = UA_STATUSCODE_GOOD;
  1091      for(size_t i = 0; i < size; ++i) {
  1092          retval |= UA_copy((void*)ptrs, (void*)ptrd, type);
  1093          ptrs += type->memSize;
  1094          ptrd += type->memSize;
  1095      }
  1096      if(retval != UA_STATUSCODE_GOOD) {
  1097          UA_Array_delete(*dst, size, type);
  1098          *dst = NULL;
  1099      }
  1100      return retval;
  1101  }
